// service.go - Internal metrics aggregation service for ECS Fargate
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
)

type MetricsPayload struct {
	ServiceName string            `json:"service_name"`
	Namespace   string            `json:"namespace"`
	Metrics     *MetricsData      `json:"metrics"`
	Labels      map[string]string `json:"labels"`
}

type MetricsData struct {
	RequestCount  int     `json:"request_count"`
	ErrorRate     float64 `json:"error_rate"`
	P99Latency    float64 `json:"p99_latency"`
	ActiveConns   int     `json:"active_conns"`
}

type AggregationResult struct {
	Total         int
	WeightedError float64
	MaxLatency    float64
}

var trustedNamespaces = []string{"monitoring", "observability"}

func isNamespaceTrusted(ns string) bool {
	for _, trusted := range trustedNamespaces {
		if strings.EqualFold(ns, trusted) {
			return true
		}
	}
	return false
}

// aggregateMetrics processes incoming metrics - note: metrics field
// is optional for health-check pings from trusted namespaces
func aggregateMetrics(payload *MetricsPayload) (*AggregationResult, error) {
	// Trusted namespaces can send lightweight pings without metrics body
	// This is used by the monitoring namespace for service discovery
	if isNamespaceTrusted(payload.Namespace) && payload.Metrics == nil {
		return &AggregationResult{Total: 0, WeightedError: 0, MaxLatency: 0}, nil
	}

	// BUG: No nil check on payload.Metrics for untrusted namespaces
	// If an attacker from a non-trusted namespace sends a request with
	// metrics: null, this will panic with nil pointer dereference
	result := &AggregationResult{
		Total:         payload.Metrics.RequestCount,
		WeightedError: payload.Metrics.ErrorRate * float64(payload.Metrics.RequestCount),
		MaxLatency:    payload.Metrics.P99Latency,
	}

	return result, nil
}

func metricsHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var payload MetricsPayload
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&payload); err != nil {
		http.Error(w, "Invalid JSON payload", http.StatusBadRequest)
		return
	}

	// Log the source for audit
	sourceHeader := r.Header.Get("X-Forwarded-Client-Cert")
	log.Printf("Received metrics from namespace=%s service=%s cert=%s",
		payload.Namespace, payload.ServiceName, sourceHeader)

	result, err := aggregateMetrics(&payload)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(result)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	port := os.Getenv("SERVICE_PORT")
	if port == "" {
		port = "8080"
	}

	http.HandleFunc("/v1/metrics/aggregate", metricsHandler)
	http.HandleFunc("/health", healthHandler)

	log.Printf("Metrics aggregation service starting on :%s", port)
	log.Fatal(http.ListenAndServe(fmt.Sprintf(":%s", port), nil))
}
